import json
with open('/app/resources/treasury_bulletin_1982_08.json', 'r') as f:
    data = json.load(f)

# Look for tables with AY-1 data
def find_in_dict(d, target):
    if isinstance(d, dict):
        for k, v in d.items():
            if target.lower() in str(k).lower():
                print(f'Found: {k}')
            find_in_dict(v, target)
    elif isinstance(d, list):
        for item in d:
            find_in_dict(item, target)

find_in_dict(data, 'yield')
